-- MEND UK Phase 6: Quotes & Scope
alter table public.quotes enable row level security;
alter table public.quote_items enable row level security;
alter table public.change_orders enable row level security;
create index if not exists idx_quotes_repair_status on public.quotes(repair_id,status,created_at desc);
create index if not exists idx_quotes_trade_status on public.quotes(trade_id,status,created_at desc);
create index if not exists idx_quote_items_quote on public.quote_items(quote_id);
create index if not exists idx_change_orders_repair on public.change_orders(repair_id,status,created_at desc);
drop policy if exists "quotes involved read" on public.quotes;
create policy "quotes involved read" on public.quotes for select to authenticated using (exists(select 1 from public.repairs r where r.id=repair_id and (r.customer_id=(select auth.uid()) or r.assigned_trade_id=trade_id)) or exists(select 1 from public.trade_profiles tp where tp.id=trade_id and tp.user_id=(select auth.uid())) or public.is_admin());
drop policy if exists "quotes trade write" on public.quotes;
create policy "quotes trade write" on public.quotes for all to authenticated using (exists(select 1 from public.trade_profiles tp where tp.id=trade_id and (tp.user_id=(select auth.uid()) or public.is_admin()))) with check (exists(select 1 from public.trade_profiles tp where tp.id=trade_id and (tp.user_id=(select auth.uid()) or public.is_admin())));
drop policy if exists "quote items involved read" on public.quote_items;
create policy "quote items involved read" on public.quote_items for select to authenticated using (exists(select 1 from public.quotes q join public.repairs r on r.id=q.repair_id where q.id=quote_id and (r.customer_id=(select auth.uid()) or exists(select 1 from public.trade_profiles tp where tp.id=q.trade_id and tp.user_id=(select auth.uid())) or public.is_admin())));
drop policy if exists "quote items trade write" on public.quote_items;
create policy "quote items trade write" on public.quote_items for all to authenticated using (exists(select 1 from public.quotes q join public.trade_profiles tp on tp.id=q.trade_id where q.id=quote_id and (tp.user_id=(select auth.uid()) or public.is_admin()) and q.status='draft')) with check (exists(select 1 from public.quotes q join public.trade_profiles tp on tp.id=q.trade_id where q.id=quote_id and (tp.user_id=(select auth.uid()) or public.is_admin()) and q.status='draft')));
drop policy if exists "change orders involved read" on public.change_orders;
create policy "change orders involved read" on public.change_orders for select to authenticated using (exists(select 1 from public.repairs r where r.id=repair_id and (r.customer_id=(select auth.uid()) or r.assigned_trade_id in (select id from public.trade_profiles where user_id=(select auth.uid())) or public.is_admin())));
drop policy if exists "change orders participant insert" on public.change_orders;
create policy "change orders participant insert" on public.change_orders for insert to authenticated with check (requested_by=(select auth.uid()) and exists(select 1 from public.repairs r where r.id=repair_id and (r.customer_id=(select auth.uid()) or r.assigned_trade_id in (select id from public.trade_profiles where user_id=(select auth.uid())) or public.is_admin())));
create or replace function public.prevent_accepted_quote_mutation() returns trigger language plpgsql as $$ begin if old.status='accepted' and (new.status is distinct from old.status or new.total is distinct from old.total or new.subtotal is distinct from old.subtotal or new.tax is distinct from old.tax or new.discount is distinct from old.discount or new.scope_description is distinct from old.scope_description or new.included_work is distinct from old.included_work or new.excluded_work is distinct from old.excluded_work or new.warranty_days is distinct from old.warranty_days or new.valid_until is distinct from old.valid_until) then raise exception 'Accepted quotes are immutable; use a change order.'; end if; return new; end; $$;
drop trigger if exists trg_quotes_immutable on public.quotes;
create trigger trg_quotes_immutable before update on public.quotes for each row execute function public.prevent_accepted_quote_mutation();
create or replace function public.accept_quote(p_quote_id uuid) returns public.quotes language plpgsql security invoker set search_path = public as $$ declare q public.quotes; r public.repairs; begin select * into q from public.quotes where id=p_quote_id for update; if not found then raise exception 'Quote not found'; end if; select * into r from public.repairs where id=q.repair_id for update; if not found or r.customer_id <> (select auth.uid()) then raise exception 'Not authorised'; end if; if q.status not in ('sent','viewed') then raise exception 'Only an active quote can be accepted'; end if; if q.valid_until is not null and q.valid_until < now() then raise exception 'Quote has expired'; end if; if exists(select 1 from public.quotes where repair_id=q.repair_id and status='accepted') then raise exception 'Another quote is already accepted'; end if; update public.quotes set status='accepted', updated_at=now() where id=q.id returning * into q; update public.quotes set status='cancelled', updated_at=now() where repair_id=q.repair_id and id<>q.id and status in ('sent','viewed','draft'); update public.repairs set assigned_trade_id=q.trade_id, estimated_price=q.total, status='accepted', updated_at=now() where id=q.repair_id; insert into public.repair_status_history(repair_id,from_status,to_status,actor_id,note) values(q.repair_id,r.status,'accepted',(select auth.uid()),'Quote accepted'); return q; end; $$;
revoke execute on function public.accept_quote(uuid) from anon;
grant execute on function public.accept_quote(uuid) to authenticated;
create or replace function public.respond_change_order(p_change_order_id uuid, p_approve boolean) returns public.change_orders language plpgsql security invoker set search_path=public as $$ declare co public.change_orders; r public.repairs; begin select * into co from public.change_orders where id=p_change_order_id for update; if not found then raise exception 'Change order not found'; end if; select * into r from public.repairs where id=co.repair_id; if r.customer_id <> (select auth.uid()) then raise exception 'Only the customer can approve a change order'; end if; if co.status <> 'requested' then raise exception 'Change order is no longer awaiting approval'; end if; if p_approve then update public.change_orders set status='approved', approved_by=(select auth.uid()), approved_at=now() where id=co.id returning * into co; else update public.change_orders set status='declined' where id=co.id returning * into co; end if; return co; end; $$;
revoke execute on function public.respond_change_order(uuid,boolean) from anon;
grant execute on function public.respond_change_order(uuid,boolean) to authenticated;
